194	    /**
195	     * Builds the owner's customer code, formatted {@code <REGION>-<HASH8>} where REGION is the region
196	     * code derived from the owner's postcode (falling back to the city-to-region table, then
197	     * {@code UNKNOWN}) and HASH8 is the first 8 upper-cased hex characters of the SHA-256 of the
198	     * owner's normalized telephone concatenated with its last name (e.g. {@code NSW-1A2B3C4D}).
199	     *
200	     * <p>Should the computed code collide with an existing owner's {@code customerCode}, it is
201	     * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
202	     * unique (e.g. {@code NSW-1A2B3C4D-2}), so distinct owners always receive distinct customer codes.
203	     *
204	     * @param owner the owner being created, with its normalized telephone already applied
205	     * @return the assigned, de-duplicated customer code
206	     */
207	    private String customerCode(Owner owner) {
208	        String base = regionCode(owner) + "-" + identityHash8(owner.getTelephone(), owner.getLastName());
209	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
210	            .map(Owner::getCustomerCode)
211	            .filter(code -> code != null)
212	            .collect(java.util.stream.Collectors.toSet());
213	        if (!existingCodes.contains(base)) {
214	            return base;
215	        }
216	        int n = 2;
217	        while (existingCodes.contains(base + "-" + n)) {
218	            n++;
219	        }
220	        return base + "-" + n;
221	    }
222	
223	    /**
224	     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
225	     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
226	     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
227	     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
228	     * postcode nor the city identifies a region.
229	     *
230	     * @param owner the owner being created
231	     * @return the derived region code, never {@code null}
232	     */
233	    private String regionCode(Owner owner) {
234	        String fromPostcode = regionFromPostcode(owner.getPostcode());
235	        if (fromPostcode != null) {
236	            return fromPostcode;
237	        }
238	        String fromCity = region(owner.getCity());
239	        return fromCity == null ? "UNKNOWN" : fromCity;
240	    }
