263	    /**
264	     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
265	     * characters of the SHA-256 of the owner's normalized telephone concatenated with its last name.
266	     *
267	     * @param telephone the owner's normalized (E.164) telephone
268	     * @param lastName  the owner's last name
269	     * @return the 8-character upper-cased hex hash
270	     */
271	    private String identityHash8(String telephone, String lastName) {
272	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
273	        try {
274	            byte[] digest = MessageDigest.getInstance("SHA-256")
275	                .digest(input.getBytes(StandardCharsets.UTF_8));
276	            StringBuilder hex = new StringBuilder(digest.length * 2);
277	            for (byte b : digest) {
278	                hex.append(String.format("%02x", b));
279	            }
280	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
281	        } catch (NoSuchAlgorithmException ex) {
282	            throw new IllegalStateException("SHA-256 not available", ex);
283	        }
284	    }
