286	    /**
287	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
288	     * last two digits of the registrationDate year, zero-padded (e.g. {@code NSW-1A2B3C4D-M26}).
289	     *
290	     * @param customerCode     the owner's assigned customer code
291	     * @param registrationDate the owner's registration date
292	     * @return the assigned membership number
293	     */
294	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
295	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
