314	    /**
315	     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
316	     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
317	     * still resemble an existing owner: when it shares an existing owner's lastName (compared
318	     * case-insensitively) and postcode while carrying a different telephone, the owner is flagged
319	     * with {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing
320	     * owner's id. When no such owner exists the flag is set to {@code false} and no match id is
321	     * recorded. An owner with no postcode can never soft-match and is always {@code false}.
322	     *
323	     * <p>A declared household member (created with {@code sharesHousehold=true}) is never a suspected
324	     * duplicate: its match with an existing household member is a deliberate, declared one, so it is
325	     * always flagged {@code false}.
326	     *
327	     * @param owner           the owner being created, with its normalized telephone already applied
328	     * @param sharesHousehold whether the request declared it shares a household; a declared member is
329	     *                        never flagged as a possible duplicate
330	     */
331	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
332	        Owner match = sharesHousehold ? null : findPossibleDuplicate(owner);
333	        if (match != null) {
334	            owner.setPossibleDuplicate(true);
335	            owner.setPossibleDuplicateOf(match.getId());
336	        } else {
337	            owner.setPossibleDuplicate(false);
338	            owner.setPossibleDuplicateOf(null);
339	        }
340	    }
