342	    /**
343	     * Finds the existing owner this owner soft-matches: same lastName (case-insensitive) and same
344	     * postcode, but a different telephone. When several existing owners match, the one with the
345	     * lowest id is chosen so the result is deterministic. Returns {@code null} when the owner has no
346	     * postcode or no such existing owner exists.
347	     *
348	     * @param owner the owner being created
349	     * @return the matching existing owner, or {@code null} when there is no soft-match
350	     */
351	    private Owner findPossibleDuplicate(Owner owner) {
352	        if (isBlank(owner.getPostcode())) {
353	            return null;
354	        }
355	        return this.clinicService.findAllOwners().stream()
356	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
357	                && owner.getPostcode().equals(existing.getPostcode())
358	                && !equalsIgnoreCase(existing.getTelephone(), owner.getTelephone()))
359	            .min(Comparator.comparing(Owner::getId))
360	            .orElse(null);
361	    }
