483	    /**
484	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
485	     * is optional and accepted, keeping the create contract backward-compatible. When present the
486	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
487	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
488	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
489	     *
490	     * @param postcode the raw postcode value as submitted, may be {@code null}
491	     * @param city     the owner's city, used to resolve the region whose range applies
492	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
493	     *                                  the city's region
494	     */
495	    private void validatePostcode(String postcode, String city) {
496	        if (isBlank(postcode)) {
497	            return;
498	        }
499	        if (!postcode.matches("[0-9]{4}")) {
500	            throw new InvalidPostcodeException(postcode, city);
501	        }
502	        String region = region(city);
503	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
504	        if (range != null) {
505	            int value = Integer.parseInt(postcode);
506	            if (value < range[0] || value > range[1]) {
507	                throw new InvalidPostcodeException(postcode, city);
508	            }
509	        }
510	    }
