512	    /**
513	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
514	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
515	     *
516	     * @param city the owner's city
517	     * @return the region code, or {@code null} when the city has no known region
518	     */
519	    private String region(String city) {
520	        if (city == null) {
521	            return null;
522	        }
523	        return switch (city) {
524	            case "Sydney" -> "NSW";
525	            case "Melbourne" -> "VIC";
526	            case "Brisbane" -> "QLD";
527	            default -> null;
528	        };
529	    }
