531	    /**
532	     * The number of national (subscriber) digits an E.164 number must carry for a given country
533	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
534	     * national digits and the North American Numbering Plan ('+1') requires 10.
535	     */
536	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
537	        Map.of("61", 9, "1", 10);
538	
539	    /**
540	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
541	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
542	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
543	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
544	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
545	     *
546	     * @param telephone the raw telephone value as submitted
547	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
548	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
549	     *                                   national-number length is wrong for its country code
550	     */
551	    private String normalizeTelephone(String telephone) {
552	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
553	        String nationalSignificantNumber;
554	        if (cleaned.startsWith("+")) {
555	            nationalSignificantNumber = cleaned.substring(1);
556	        } else {
557	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
558	            nationalSignificantNumber = "61" + national;
559	        }
560	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
561	            throw new InvalidTelephoneException(telephone);
562	        }
563	        validateNationalNumberLength(nationalSignificantNumber, telephone);
564	        return "+" + nationalSignificantNumber;
565	    }
566	
567	    /**
568	     * Validates the national-number length of an E.164 number against its country calling code. The
569	     * significant number is a country code immediately followed by the national digits; for each
570	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
571	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
572	     * left unchecked.
573	     *
574	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
575	     * @param rejectedValue             the raw telephone value, reported on rejection
576	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
577	     */
578	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
579	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
580	            String countryCode = rule.getKey();
581	            if (nationalSignificantNumber.startsWith(countryCode)) {
582	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
583	                if (nationalDigits != rule.getValue()) {
584	                    throw new InvalidTelephoneException(rejectedValue);
585	                }
586	                return;
587	            }
588	        }
589	    }
