591	    /**
592	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
593	     * value is treated as absent and returns {@code null}); when present the value must be a
594	     * syntactically valid address, and is stored and returned lower-cased.
595	     *
596	     * @param email the raw email value as submitted, may be {@code null}
597	     * @return the lower-cased email, or {@code null} when none was supplied
598	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
599	     */
600	    private String normalizeEmail(String email) {
601	        if (email == null || email.isBlank()) {
602	            return null;
603	        }
604	        String normalized = email.trim().toLowerCase();
605	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
606	            throw new InvalidEmailException(email);
607	        }
608	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
609	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
610	            throw new DisposableEmailException(email);
611	        }
612	        return normalized;
613	    }
