615	    /**
616	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
617	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
618	     * key is the normalized telephone, email and householdId joined together, this one check
619	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
620	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
621	     * with different telephones have different keys and are both allowed.
622	     *
623	     * @param owner the owner being created, with its normalized telephone, email and householdId
624	     *              already applied
625	     * @throws DuplicateIdentityException if another owner already has the same identityKey
626	     */
627	    private void rejectDuplicateIdentity(Owner owner) {
628	        String identityKey = identityKey(owner);
629	        boolean inUse = this.clinicService.findAllOwners().stream()
630	            .map(this::identityKey)
631	            .anyMatch(identityKey::equals);
632	        if (inUse) {
633	            throw new DuplicateIdentityException(identityKey);
634	        }
635	    }
