637	    /**
638	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
639	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
640	     * duplicate decision is made by comparing whole identityKeys.
641	     *
642	     * @param owner the owner whose identityKey to derive
643	     * @return the derived identityKey
644	     */
645	    private String identityKey(Owner owner) {
646	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
647	        String email = owner.getEmail() == null ? "" : owner.getEmail();
648	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
649	        return telephone + "|" + email + "|" + householdId;
