652	    /**
653	     * Applies the household rule to an owner being created. The household is keyed on
654	     * (lastName, postcode): the owner is assigned the deterministic {@link #householdId(Owner)
655	     * householdId} derived from its normalized lastName and postcode, so owners sharing a lastName
656	     * and postcode automatically share the identifier — the link is computed, not created by a flag.
657	     *
658	     * <p>Because the household is keyed on (lastName, postcode), any existing owner that derives the
659	     * same householdId is a member of the same household, and a second owner joining it is a
660	     * household duplicate. Such a create is rejected with 409 unless the request declares
661	     * {@code sharesHousehold=true}, in which case it is allowed through as a declared household
662	     * member. The {@code sharesHousehold} directive only bypasses this duplicate block.
663	     *
664	     * @param owner           the owner being created
665	     * @param sharesHousehold whether the request declared it shares a household, bypassing the block
666	     * @throws HouseholdDuplicateException if an existing owner already shares the household and the
667	     *                                     request did not declare {@code sharesHousehold=true}
668	     */
669	    private void applyHousehold(Owner owner, boolean sharesHousehold) {
670	        String householdId = householdId(owner);
671	        owner.setHouseholdId(householdId);
672	        boolean householdExists = this.clinicService.findAllOwners().stream()
673	            .anyMatch(existing -> householdId.equals(householdId(existing)));
674	        if (householdExists && !sharesHousehold) {
675	            throw new HouseholdDuplicateException(householdId);
676	        }
677	    }
