679	    /**
680	     * Derives the stable, shared household identifier for an owner, formatted {@code HH-<HEX12>}
681	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the owner's normalized
682	     * lastName, a {@code '|'} separator, and its postcode. Being a pure function of (lastName,
683	     * postcode), every owner sharing a lastName and postcode derives the same value regardless of
684	     * creation order. A {@code null} postcode contributes an empty segment.
685	     *
686	     * @param owner the owner whose household identifier to derive
687	     * @return the household identifier
688	     */
689	    private String householdId(Owner owner) {
690	        String lastNameKey = toHouseholdKey(owner.getLastName());
691	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
692	        try {
693	            byte[] digest = MessageDigest.getInstance("SHA-256")
694	                .digest((lastNameKey + "|" + postcode).getBytes(StandardCharsets.UTF_8));
695	            StringBuilder hex = new StringBuilder(digest.length * 2);
696	            for (byte b : digest) {
697	                hex.append(String.format("%02x", b));
698	            }
699	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
700	        } catch (NoSuchAlgorithmException ex) {
701	            throw new IllegalStateException("SHA-256 not available", ex);
702	        }
703	    }
