705	    /**
706	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
707	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
708	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
709	     * string.
710	     */
711	    private String toHouseholdKey(String value) {
712	        if (value == null) {
713	            return "";
714	        }
715	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
716	    }
717	
718	    /**
719	     * Applies the owner's address, preferring the structured form over the flat one. The structured
720	     * {@code addressLine1}/{@code addressLine2} and the flat {@code address} are each normalized (see
721	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
722	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (a
723	     * blank {@code addressLine2} is stored as {@code null}), and the composed {@code address} is the
724	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
725	     * appended when an {@code addressLine2} is present. Otherwise the flat {@code address} is used for
726	     * backward compatibility: the normalized flat value becomes both {@code addressLine1} and the
727	     * stored {@code address}, with no {@code addressLine2}. Everything that later reads the owner's
728	     * address therefore sees the structured value when present, falling back to the flat one.
729	     *
730	     * @param owner the owner being created
731	     * @param dto   the submitted owner fields
732	     */
733	    private void applyAddress(Owner owner, OwnerFieldsDto dto) {
734	        String line1 = normalizeAddress(dto.getAddressLine1());
735	        String line2 = normalizeAddress(dto.getAddressLine2());
736	        String flat = normalizeAddress(dto.getAddress());
737	        String effectiveLine1 = line1.isEmpty() ? flat : line1;
738	        String effectiveLine2 = line1.isEmpty() ? "" : line2;
739	        String composed = effectiveLine2.isEmpty()
740	            ? effectiveLine1
741	            : effectiveLine1 + " " + effectiveLine2;
742	        owner.setAddressLine1(effectiveLine1.isEmpty() ? null : effectiveLine1);
743	        owner.setAddressLine2(effectiveLine2.isEmpty() ? null : effectiveLine2);
744	        owner.setAddress(composed);
745	    }
746	
747	    /**
748	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
749	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
750	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
751	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
752	     * value, or one that is blank once trimmed, normalizes to an empty string.
753	     *
754	     * @param address the raw address value as submitted, may be {@code null}
755	     * @return the normalized address, or an empty string when none was supplied
756	     */
757	    private String normalizeAddress(String address) {
758	        if (address == null) {
759	            return "";
760	        }
761	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
762	        if (collapsed.isEmpty()) {
763	            return "";
764	        }
765	        String[] tokens = collapsed.split(" ");
766	        StringBuilder normalized = new StringBuilder(collapsed.length());
767	        for (int i = 0; i < tokens.length; i++) {
768	            if (i > 0) {
769	                normalized.append(' ');
770	            }
771	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
772	        }
773	        return normalized.toString();
774	    }
775	
776	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
777	    @Override
778	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
779	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
780	        if (currentOwner == null) {
781	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
782	        }
783	        currentOwner.setAddress(ownerFieldsDto.getAddress());
784	        currentOwner.setCity(ownerFieldsDto.getCity());
785	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
786	        currentOwner.setLastName(ownerFieldsDto.getLastName());
787	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
788	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
789	        this.clinicService.saveOwner(currentOwner);
790	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
791	    }
792	
793	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
794	    @Transactional
795	    @Override
796	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
797	        Owner owner = this.clinicService.findOwnerById(ownerId);
798	        if (owner == null) {
799	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
800	        }
801	        this.clinicService.deleteOwner(owner);
802	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
803	    }
804	
805	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
806	    @Override
807	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
808	        Owner owner = this.clinicService.findOwnerById(ownerId);
809	        if (owner == null) {
810	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
811	        }
812	        HttpHeaders headers = new HttpHeaders();
813	        Pet pet = petMapper.toPet(petFieldsDto);
814	        owner.setId(ownerId);
815	        pet.setOwner(owner);
816	        pet.getType().setName(null);
817	        this.clinicService.savePet(pet);
818	        PetDto petDto = petMapper.toPetDto(pet);
819	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
820	            .buildAndExpand(pet.getId()).toUri());
821	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
822	    }
823	
824	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
825	    @Override
826	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
827	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
828	        if (currentOwner != null) {
829	            Pet currentPet = this.clinicService.findPetById(petId);
830	            if (currentPet != null) {
831	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
832	                currentPet.setName(petFieldsDto.getName());
833	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
834	                this.clinicService.savePet(currentPet);
835	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
836	            }
837	        }
838	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
839	    }
840	
841	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
842	    @Override
843	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
844	        HttpHeaders headers = new HttpHeaders();
845	        Visit visit = visitMapper.toVisit(visitFieldsDto);
846	        Pet pet = new Pet();
847	        pet.setId(petId);
848	        visit.setPet(pet);
849	        this.clinicService.saveVisit(visit);
850	        VisitDto visitDto = visitMapper.toVisitDto(visit);
851	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
852	            .buildAndExpand(visit.getId()).toUri());
853	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
854	    }
855	
856	
857	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
858	    @Override
859	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
860	        Owner owner = this.clinicService.findOwnerById(ownerId);
861	        if (owner != null) {
862	            Pet pet = owner.getPet(petId);
863	            if (pet != null) {
864	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
865	            }
866	        }
867	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
868	    }
869	}
